#[path="../mixins/sunset/bot_packet_policy.rs"]mod packets;
use horizon_protocol::{buf::Reader,packets::play::{self,Clientbound as C}};
use horizon_core::{geometry::{Aabb,Vec3,VoxelShape},position::{BlockPos,ChunkPos}};
use horizon_world::{block_collision_scan::{BlockCollisionWorld,CollisionBlock},collision_context::CollisionContext,entity_obstruction::EntityIdentity,registry::BlockStateId,world_movement::{EntityMovementWorld,MovementRequest,resolve_world_movement},world_ray::{self,RayWorld,RayBlockMode,RayFluidMode}};
fn roundtrip(p:C)->C{let bytes=p.encode();let mut r=Reader::new(&bytes);let id=r.varint().unwrap();C::decode(id,r.rest()).unwrap()}
#[test]fn actual_native_relative_position_bits_preserve_absolute_other_axes(){let p=roundtrip(C::PlayerPosition(play::PlayerPosition{teleport:7,position:[2.,40.,-3.],delta:[0.;3],yaw:0.,pitch:0.,relatives:5}));assert_eq!(packets::correction(&p,[10.,20.,30.]),Some([12.,40.,27.]));}
#[test]fn actual_native_correction_nan_and_rotation_flags_cannot_create_movement(){let p=C::PlayerPosition(play::PlayerPosition{teleport:7,position:[2.,40.,-3.],delta:[0.;3],yaw:0.,pitch:0.,relatives:24});assert_eq!(packets::correction(&p,[10.,20.,30.]),Some([2.,40.,-3.]));assert!(packets::correction(&p,[f64::NAN,0.,0.]).is_none());}
#[test]fn actual_native_own_damage_source_zero_is_retained_and_remote_victim_ignored(){let p=roundtrip(C::DamageEvent(play::DamageEvent{id:7,source_type:1,cause:Some(0),direct:Some(0),position:None}));assert_eq!(packets::own_damage_cause(&p,7),Some(0));assert!(packets::own_damage_cause(&p,8).is_none());}
#[test]fn actual_native_totem_event_is_not_confused_with_death_or_hurt(){for event in [3,2,35]{let p=roundtrip(C::EntityEvent(play::EntityEvent{id:7,event}));assert_eq!(packets::totem(&p),if event==35{Some(7)}else{None});}}
#[test]fn actual_native_time_packet_drives_production_pause_clock(){let p=roundtrip(C::SetTime(play::SetTime{game_time:200,clocks:vec![]}));assert_eq!(packets::time(&p),Some(200));let mut clock=policy::PauseClock::default();clock.time(180,1000);clock.time(packets::time(&p).unwrap(),3000);assert_eq!(clock.tps,15.);clock.time(220,5000);assert!(clock.slow());}
#[test]fn actual_native_block_update_requires_matching_observed_world_for_setup(){let p=roundtrip(C::BlockUpdate(play::BlockUpdate{pos:[2,120,0],state:700}));let mut ledger=policy::Blocks::default();ledger.sent([2,120,0],0,1,policy::Purpose::LandingBase);if let C::BlockUpdate(p)=p{ledger.payload(p.pos,p.state as u32);}assert!(!ledger.acknowledged([2,120,0],0));assert!(ledger.acknowledged([2,120,0],700));}
#[derive(Default)]struct World{slab:bool,wall:bool,missing:bool}
impl World{fn state(&self,p:BlockPos)->u32{if p.y==0{if self.slab{2}else{1}}else if self.wall&&p.x==2&&(1..=4).contains(&p.y){1}else{0}}fn shape(state:u32)->VoxelShape{match state{0=>VoxelShape::empty(),1=>VoxelShape::block(),_=>VoxelShape::from_box(Aabb::new(Vec3::ZERO,Vec3::new(1.,0.5,1.))).unwrap()}}}
impl BlockCollisionWorld for World{type Error=();type Chunk=();fn collision_chunk(&mut self,_:ChunkPos)->Result<Option<()>,()>{if self.missing{Err(())}else{Ok(Some(()))}}fn collision_block(&mut self,_:(),p:BlockPos)->Result<CollisionBlock,()>{let state=self.state(p);Ok(CollisionBlock{state:BlockStateId(state),large_collision_shape:false,moving_piston:false,empty_shape:state==0})}fn is_suffocating(&mut self,_:(),b:CollisionBlock,_:BlockPos)->Result<bool,()>{Ok(b.state.0!=0)}fn context_shape(&mut self,b:CollisionBlock,_:BlockPos,_:&CollisionContext<'_>)->Result<VoxelShape,()>{Ok(Self::shape(b.state.0))}fn may_reach_out(&mut self,_:(),_:i32)->Result<bool,()>{Ok(false)}}
impl EntityMovementWorld for World{type Error=();fn entity_collisions(&mut self,_:EntityIdentity,_:Aabb)->Result<Vec<VoxelShape>,()>{Ok(vec![])}fn movement_border(&mut self,_:EntityIdentity,_:Aabb)->Result<Option<VoxelShape>,()>{Ok(None)}}
impl RayWorld for World{type Error=();type Block=u32;type Fluid=();fn block_state(&mut self,p:BlockPos)->Result<u32,()>{if self.missing{Err(())}else{Ok(self.state(p))}}fn fluid_state(&mut self,_:BlockPos)->Result<(),()>{Ok(())}fn block_shape(&mut self,s:u32,_:BlockPos,_:RayBlockMode)->Result<VoxelShape,()>{Ok(Self::shape(s))}fn interaction_shape(&mut self,_:u32,_:BlockPos)->Result<VoxelShape,()>{Ok(VoxelShape::empty())}fn fluid_is_source(&mut self,_:())->Result<bool,()>{Ok(false)}fn fluid_is_empty(&mut self,_:())->Result<bool,()>{Ok(true)}fn fluid_is_water(&mut self,_:())->Result<bool,()>{Ok(false)}fn fluid_shape(&mut self,_:(),_:BlockPos)->Result<VoxelShape,()>{Ok(VoxelShape::empty())}}
fn clip(world:&mut World,at:[f64;3],d:[f64;3])->Option<[f64;3]>{let lo=Vec3::new(at[0]-0.3,at[1],at[2]-0.3);let hi=Vec3::new(at[0]+0.3,at[1]+1.8,at[2]+0.3);resolve_world_movement(world,MovementRequest{entity:EntityIdentity(7),context:CollisionContext::position(at[1]),bounds:Aabb::new(lo,hi),movement:Vec3::new(d[0],d[1],d[2]),max_step:0.,on_ground:false,candidate_budget:512}).ok().map(|v|[v.x,v.y,v.z])}
#[test]fn actual_native_partial_voxel_collision_lands_on_slab_top(){let mut world=World{slab:true,..Default::default()};let stop=policy::body_path([0.5,2.,0.5],[0.;3],[0.;3],false,0.546,40,|a,d|clip(&mut world,a,d)).unwrap();assert!(stop.landed);assert!((stop.at[1]-0.5).abs()<1e-12);}
#[test]fn actual_native_wall_collision_stops_horizontal_launch_without_fabricated_teleport(){let mut world=World{wall:true,..Default::default()};let stop=policy::body_path([0.5,1.,0.5],[0.7,0.4,0.],[0.;3],true,0.546,40,|a,d|clip(&mut world,a,d)).unwrap();assert!(stop.landed);assert!(stop.at[0]<=1.7+1e-8);assert!((stop.at[1]-1.).abs()<1e-10);}
#[test]fn actual_native_friction_changes_landing_and_missing_chunk_fails_closed(){let mut world=World::default();let mut land=|friction|policy::body_path([0.5,1.,0.5],[0.7,0.4,0.],[0.;3],true,friction*0.91,40,|a,d|clip(&mut world,a,d)).unwrap();let normal=land(0.6);let ice=land(0.98);assert!(ice.at[0]>normal.at[0]+1.);world.missing=true;assert!(policy::body_path([0.5,1.,0.5],[0.;3],[0.;3],false,0.546,40,|a,d|clip(&mut world,a,d)).is_none());}
#[test]fn actual_native_collider_ray_determines_pearl_first_hit(){let mut world=World{wall:true,..Default::default()};let land=policy::pearl_path([0.5,2.,0.5],[1.5,0.,0.],|a,b|{if a==b{return Some((None,false));}let hit=world_ray::clip_world(&mut world,Vec3::new(a[0],a[1],a[2]),Vec3::new(b[0],b[1],b[2]),RayBlockMode::Collider,RayFluidMode::None,64).ok()?;Some(((!hit.miss).then_some([hit.hit.location.x,hit.hit.location.y,hit.hit.location.z]),false))}).unwrap();assert_eq!(land.ticks,2);assert!((land.at[0]-2.).abs()<1e-10);}
